                                i += 1;
                            }
                        }
                    }
                    c => sub_unexpected(&format!("-{}", c), &sub_usage(&sub_used)),
                }
                k += 1;
            }
            i += 1;
            continue;
        }
        sub_unexpected(&a, &sub_usage(&sub_used));
    }

    if width.is_none() && (!sub_used.is_empty() || height.is_some() || webify.is_some()) {
        // determine usage line: used args sorted by declaration order plus -w
        let mut order: Vec<String> = Vec::new();
        if sub_used.iter().any(|s| s == "--webify <frame count>") {
            order.push("--webify <frame count>".to_string());
        }
        if sub_used.iter().any(|s| s == "-h <height>") {
            order.push("-h <height>".to_string());
        }
        order.push("-w <width>".to_string());
        if sub_used.iter().any(|s| s == "--yaw <x>") {
            order.push("--yaw <x>".to_string());
        }
        if sub_used.iter().any(|s| s == "--pitch <y>") {
            order.push("--pitch <y>".to_string());
        }
        if sub_used.iter().any(|s| s == "--roll <z>") {
            order.push("--roll <z>".to_string());
        }
        let mut usage = format!("{} image", prog());
        for u in &order {
            usage.push(' ');
            usage.push_str(u);
        }
        sub_missing(vec!["-w <width>".to_string()], &usage);
    }

    if width.is_none() {
        // fall back to terminal size
        match crate_size() {
            Some((cw, _ch)) => width = Some(cw),
            None => {
                eprintln!("Error: IoError(Os {{ code: 25, kind: Uncategorized, message: \"Inappropriate ioctl for device\" }})");
                process::exit(1);
            }
        }
    }
    let w = width.unwrap();
    let h = height.unwrap_or(w);

    Args {
        inputs,
        rotate,
        blue: blue || sub_blue,
        width: Some(w),
        height: Some(h),
        webify,
        sub,
    }
}

fn is_number(s: &str) -> bool {
    if s.is_empty() {
        return false;
    }
    let t = s.strip_prefix('-').unwrap_or(s);
    !t.is_empty() && t.chars().all(|c| c.is_ascii_digit() || c == '.')
}

fn opt_val(argv: &Vec<String>, i: &mut usize, name: &str) -> Option<f32> {
    match argv.get(*i + 1) {
        Some(s) if is_number(s) => {
            let v = s.parse().unwrap_or_else(|_| bad_value(name, s));
            *i += 2;
            Some(v)
        }
        _ => {
            *i += 1;
            Some(0.0)
        }
    }
}

fn sub_opt_val(
    argv: &Vec<String>,
    i: &mut usize,
    name: &str,
    used: &mut Vec<String>,
    snip: &str,
) -> Option<f32> {
    used.push(snip.to_string());
    match argv.get(*i + 1) {
        Some(s) if is_number(s) => {
            let v = s.parse().unwrap_or_else(|_| bad_value(name, s));
            *i += 2;
            Some(v)
        }
        _ => {
            *i += 1;
            Some(0.0)
        }
    }
}

fn sub_usage(used: &Vec<String>) -> String {
    let mut order: Vec<String> = Vec::new();
    if used.iter().any(|s| s == "--webify <frame count>") {
        order.push("--webify <frame count>".to_string());
    }
    if used.iter().any(|s| s == "-h <height>") {
        order.push("-h <height>".to_string());
    }
    if used.iter().any(|s| s == "-w <width>") {
        order.push("-w <width>".to_string());
    }
    if used.iter().any(|s| s == "--yaw <x>") {
        order.push("--yaw <x>".to_string());
    }
    if used.iter().any(|s| s == "--pitch <y>") {
        order.push("--pitch <y>".to_string());
    }
    if used.iter().any(|s| s == "--roll <z>") {
        order.push("--roll <z>".to_string());
    }
    if order.is_empty() {
        return format!("{} image -h <height> -w <width>", prog());
    }
    let mut u = format!("{} image", prog());
    for o in &order {
        u.push(' ');
        u.push_str(o);
    }
    u
}

pub fn crate_size() -> Option<(usize, usize)> {
    unsafe {
        #[repr(C)]
        struct Winsize {
            row: u16,
            col: u16,
            x: u16,
            y: u16,
        }
        extern "C" {
            fn ioctl(fd: i32, req: u64, ...) -> i32;
        }
        let mut ws = Winsize { row: 0, col: 0, x: 0, y: 0 };
        let r = ioctl(1, 0x5413, &mut ws as *mut Winsize);
        if r == 0 && ws.col > 0 {
            Some((ws.col as usize, ws.row as usize))
        } else {
            None
        }
    }
}
