// Command line parsing that reproduces the observed clap-v2 style output.
use std::process;

pub const APP_NAME: &str = "Sloth";
pub const APP_VERSION: &str = "0.1";
pub const MAIN_AUTHOR: &str = "Mitchell Hynes. <mshynes@mun.ca>";
pub const MAIN_ABOUT: &str = "A toy for rendering 3D objects in the command line";
pub const SUB_AUTHOR: &str = "Mitchell Hynes <mitchell.hynes@ecumene.xyz>";
pub const SUB_ABOUT: &str = "Generates a colorless terminal output as lines of text";

#[derive(Clone, Copy, PartialEq)]
pub enum Rot { X, Y, Z }

#[derive(Clone)]
pub struct Rotate {
    pub x: Option<f32>,
    pub y: Option<f32>,
    pub z: Option<f32>,
}

#[derive(Clone)]
pub struct Args {
    pub inputs: Vec<String>,
    pub rotate: Rotate,
    pub blue: bool,
    pub width: Option<usize>,
    pub height: Option<usize>,
    pub webify: Option<usize>,
    pub sub: Option<String>,
}

pub fn prog() -> String {
    std::env::args().next().unwrap_or_else(|| "sloth".to_string())
}

pub fn main_usage() -> String {
    format!("{} [FLAGS] [OPTIONS] <input filename(s)>... [SUBCOMMAND]", prog())
}

pub fn main_help() -> String {
    format!(
        "{} {}\n{}\n{}\n\nUSAGE:\n    {}\n\nFLAGS:\n    -h, --help       Prints help information\n    -b               Flags the rasterizer to render without color\n    -V, --version    Prints version information\n\nOPTIONS:\n    -x, --yaw <x>      Sets the object's static X rotation (in radians)\n    -y, --pitch <y>    Sets the object's static Y rotation (in radians)\n    -z, --roll <z>     Sets the object's static Z rotation (in radians)\n\nARGS:\n    <input filename(s)>...    Sets the input file to render\n\nSUBCOMMANDS:\n    help     Prints this message or the help of the given subcommand(s)\n    image    Generates a colorless terminal output as lines of text\n",
        APP_NAME, APP_VERSION, MAIN_AUTHOR, MAIN_ABOUT, main_usage()
    )
}

pub fn version_line() -> String {
    format!("{} {}\n", APP_NAME, APP_VERSION)
}

pub fn sub_help_usage() -> String {
    format!("{} <input filename(s)>... image [FLAGS] [OPTIONS] -w <width>", prog())
}

pub fn sub_help_plain_usage() -> String {
    format!("{} image [FLAGS] [OPTIONS] -w <width>", prog())
}

pub fn image_help(usage: &str) -> String {
    format!(
        "{}-image \n{}\n{}\n\nUSAGE:\n    {}\n\nFLAGS:\n        --help       Prints help information\n    -b               Flags the rasterizer to render without color\n    -V, --version    Prints version information\n\nOPTIONS:\n    -j, --webify <frame count>    Generates a portable JS based render of your object for the web\n    -h <height>                   Sets the height of the image to generate\n    -w <width>                    Sets the width of the image to generate\n    -x, --yaw <x>                 Sets the object's static X rotation (in radians)\n    -y, --pitch <y>               Sets the object's static Y rotation (in radians)\n    -z, --roll <z>                Sets the object's static Z rotation (in radians)\n",
        prog(), SUB_AUTHOR, SUB_ABOUT, usage
    )
}

pub fn sub_version() -> String {
    format!("{}-image \n", prog())
}

fn err_exit(msg: String) -> ! {
    eprint!("{}", msg);
    process::exit(1)
}

fn missing(args: Vec<String>, usage: &str) -> ! {
    let mut s = String::from("error: The following required arguments were not provided:\n");
    for a in &args {
        s.push_str("    ");
        s.push_str(a);
        s.push('\n');
    }
    s.push_str(&format!("\nUSAGE:\n    {}\n\nFor more information try --help\n", usage));
    err_exit(s)
}

fn unexpected(arg: &str, usage: &str) -> ! {
    err_exit(format!(
        "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
        arg, usage
    ))
}

fn needs_value(arg: &str, usage: &str) -> ! {
    err_exit(format!(
        "error: The argument '{}' requires a value but none was supplied\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
        arg, usage
    ))
}

fn bad_value(arg: &str, val: &str) -> ! {
    err_exit(format!(
        "error: Invalid value for '{}': '{}'\n\nFor more information try --help\n",
        arg, val
    ))
}

fn sub_err_exit(msg: String) -> ! {
    eprint!("{}", msg);
    process::exit(1)
}

fn sub_missing(args: Vec<String>, usage: &str) -> ! {
    let mut s = String::from("error: The following required arguments were not provided:\n");
    for a in &args {
        s.push_str("    ");
        s.push_str(a);
        s.push('\n');
    }
    s.push_str(&format!("\nUSAGE:\n    {}\n\nFor more information try --help\n", usage));
    sub_err_exit(s)
}

fn sub_unexpected(arg: &str, usage: &str) -> ! {
    sub_err_exit(format!(
        "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
        arg, usage
    ))
}

fn sub_needs_value(arg: &str, usage: &str) -> ! {
    sub_err_exit(format!(
        "error: The argument '{}' requires a value but none was supplied\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
        arg, usage
    ))
}

/// Rotation option usage snippet, ordered by declaration order (x, y, z).
fn rot_snip(r: &Rotate) -> Vec<String> {
    let mut v = Vec::new();
    if r.x.is_some() {
        v.push("--yaw <x>".to_string());
    }
    if r.y.is_some() {
        v.push("--pitch <y>".to_string());
    }
    if r.z.is_some() {
        v.push("--roll <z>".to_string());
    }
    v
}

pub fn parse() -> Args {
    let argv: Vec<String> = std::env::args().skip(1).collect();
    let mut i = 0usize;
    let mut inputs: Vec<String> = Vec::new();
    let mut rotate = Rotate { x: None, y: None, z: None };
    let mut blue = false;
    let mut sub: Option<String> = None;
    let mut seen_dashdash = false;

    while i < argv.len() {
        let a = argv[i].clone();
        if !seen_dashdash && a == "--" {
            seen_dashdash = true;
            i += 1;
            continue;
        }
        if !seen_dashdash && a.starts_with("--") {
            match a.as_str() {
                "--help" => {
                    print!("{}", main_help());
                    process::exit(0);
                }
                "--version" => {
                    print!("{}", version_line());
                    process::exit(0);
                }
                "--yaw" => {
                    let v = argv.get(i + 1).cloned();
                    match v {
                        Some(s) if !s.starts_with('-') || s.len() == 1 => {
                            rotate.x = Some(s.parse().unwrap_or_else(|_| bad_value("--yaw", &s)));
                            i += 2;
                        }
                        Some(s) => {
                            // --yaw=-0.5 style
                            if let Some(stripped) = s.strip_prefix("--yaw=") {
                                rotate.x = Some(
                                    stripped
                                        .parse()
                                        .unwrap_or_else(|_| bad_value("--yaw", stripped)),
                                );
                                i += 1;
                            } else {
                                rotate.x = Some(0.0);
                                i += 1;
                            }
                        }
                        None => {
                            rotate.x = Some(0.0);
                            i += 1;
                        }
                    }
