                    rotate.y = opt_val(&argv, &mut i, "--pitch");
                    continue;
                }
                "--roll" => {
                    rotate.z = opt_val(&argv, &mut i, "--roll");
                    continue;
                }
                "--yaw=" | _ => {
                    if let Some(rest) = a.strip_prefix("--yaw=") {
                        rotate.x = Some(rest.parse().unwrap_or_else(|_| bad_value("--yaw", rest)));
                        i += 1;
                        continue;
                    }
                    if let Some(rest) = a.strip_prefix("--pitch=") {
                        rotate.y = Some(rest.parse().unwrap_or_else(|_| bad_value("--pitch", rest)));
                        i += 1;
                        continue;
                    }
                    if let Some(rest) = a.strip_prefix("--roll=") {
                        rotate.z = Some(rest.parse().unwrap_or_else(|_| bad_value("--roll", rest)));
                        i += 1;
                        continue;
                    }
                    unexpected(&a, &main_usage());
