            }
        }
        if !seen_dashdash && a.starts_with('-') && a.len() > 1 {
            // short flag cluster
            let chars: Vec<char> = a[1..].chars().collect();
            let mut k = 0usize;
            while k < chars.len() {
                match chars[k] {
                    'h' => {
                        print!("{}", main_help());
