// Model loading: Wavefront OBJ (+ MTL) and STL.
use std::fs;
use std::path::Path;

#[derive(Clone, Copy, Debug)]
pub struct Vertex {
    pub position: [f32; 3],
}

#[derive(Clone, Copy, Debug)]
pub struct Triangle {
    pub vertices: [usize; 3],
    pub material: usize,
}

#[derive(Clone, Debug)]
pub struct Material {
    pub name: String,
    pub diffuse: [f32; 3],
}

#[derive(Debug)]
pub enum Error {
    OpenFileFailed,
    Parse(String),
}

impl std::fmt::Display for Error {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        match self {
            Error::OpenFileFailed => write!(f, "OpenFileFailed"),
            Error::Parse(s) => write!(f, "{}", s),
        }
    }
}

pub struct Model {
    pub vertices: Vec<Vertex>,
    pub triangles: Vec<Triangle>,
    pub materials: Vec<Material>,
}

fn default_material() -> Material {
    Material {
        name: String::new(),
        diffuse: [1.0 / 255.0, 1.0 / 255.0, 1.0 / 255.0],
    }
}

fn parse_vec3(s: &str) -> Option<[f32; 3]> {
    let t: Vec<&str> = s.split_whitespace().collect();
    if t.len() < 3 {
        return None;
    }
    let a: Vec<f32> = t.iter().filter_map(|x| x.parse().ok()).collect();
    if a.len() < 3 {
        return None;
    }
    Some([a[0], a[1], a[2]])
}

fn parse_mtl(text: &str) -> Vec<Material> {
    let mut mats: Vec<Material> = Vec::new();
    for line in text.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let mut it = line.splitn(2, ' ');
        let key = it.next().unwrap_or("");
        let rest = it.next().unwrap_or("").trim();
        match key {
            "newmtl" => {
                mats.push(Material {
                    name: rest.to_string(),
                    diffuse: [0.0, 0.0, 0.0],
                });
            }
            "Kd" => {
                if let Some(v) = parse_vec3(rest) {
                    if let Some(m) = mats.last_mut() {
                        m.diffuse = v;
                    }
                }
            }
            _ => {}
        }
    }
    mats
}

fn load_mtl(path: &str) -> Result<Vec<Material>, Error> {
    let text = match fs::read_to_string(path) {
        Ok(t) => t,
        Err(_) => return Err(Error::OpenFileFailed),
    };
    Ok(parse_mtl(&text))
}

/// Resolve the mtllib path relative to the obj file's directory.
fn resolve(base_dir: &str, lib: &str) -> String {
    if lib.starts_with('/') {
        return lib.to_string();
    }
    if base_dir.is_empty() {
        return lib.to_string();
    }
    format!("{}/{}", base_dir.trim_end_matches('/'), lib)
}

pub fn load_obj(path: &str) -> Result<Model, Error> {
    let text = match fs::read_to_string(path) {
        Ok(t) => t,
        Err(_) => return Err(Error::OpenFileFailed),
    };
    let base_dir = {
        let p = Path::new(path);
        match p.parent() {
            Some(d) => d.to_str().unwrap_or("").to_string(),
            None => String::new(),
        }
    };
    let mut vertices: Vec<Vertex> = Vec::new();
    let mut triangles: Vec<Triangle> = Vec::new();
    let mut materials: Vec<Material> = Vec::new();
    let mut cur_mat: Option<usize> = None;

    for line in text.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let mut it = line.splitn(2, ' ');
        let key = it.next().unwrap_or("");
        let rest = it.next().unwrap_or("").trim();
        match key {
            "v" => {
                if let Some(v) = parse_vec3(rest) {
                    vertices.push(Vertex { position: v });
                }
            }
            "vn" | "vt" => {}
            "mtllib" => {
                let lib = rest.split_whitespace().next().unwrap_or("");
                if !lib.is_empty() {
                    let p = resolve(&base_dir, lib);
                    if materials.is_empty() {
                        match load_mtl(&p) {
                            Ok(m) => {
                                for x in m {
                                    materials.push(x);
                                }
                            }
                            Err(e) => {
                                return Err(e);
                            }
                        }
                    }
                }
            }
            "usemtl" => {
                let name = rest.trim().to_string();
                cur_mat = materials.iter().position(|m| m.name == name);
            }
            "f" => {
                let idx: Vec<i64> = rest
                    .split_whitespace()
                    .map(|s| {
                        let first = s.split('/').next().unwrap_or("0");
                        first.parse::<i64>().unwrap_or(0)
                    })
                    .collect();
                if idx.len() < 3 {
                    continue;
                }
                let n = vertices.len() as i64;
                let mut vi: Vec<usize> = Vec::new();
                for i in idx {
                    let v = if i > 0 { i - 1 } else { n + i };
                    if v < 0 || v as usize >= vertices.len() {
                        continue;
                    }
                    vi.push(v as usize);
                }
                for k in 1..vi.len().saturating_sub(1) {
                    triangles.push(Triangle {
                        vertices: [vi[0], vi[k], vi[k + 1]],
                        material: cur_mat.unwrap_or(usize::MAX),
                    });
                }
            }
            _ => {}
        }
    }
    if cur_mat.is_none() && materials.is_empty() {
        materials.push(default_material());
        cur_mat = Some(0);
    }
    for t in triangles.iter_mut() {
        if t.material == usize::MAX {
            t.material = 0;
        }
    }
    Ok(Model {
        vertices,
        triangles,
        materials,
    })
}

/// Load an STL file (ascii or binary) returning vertices + triangles with a
/// single default (yellow) material.
pub fn load_stl(path: &str) -> Result<Model, Error> {
    let data = match fs::read(path) {
        Ok(d) => d,
        Err(_) => return Err(Error::OpenFileFailed),
    };
    let mut vertices: Vec<Vertex> = Vec::new();
    let mut triangles: Vec<Triangle> = Vec::new();
    let is_binary = {
        if data.len() >= 84 {
            let n = u32::from_le_bytes([data[80], data[81], data[82], data[83]]) as usize;
            n > 0 && data.len() >= 84 + n * 50
        } else {
            false
        }
    };
    if is_binary {
        let n = u32::from_le_bytes([data[80], data[81], data[82], data[83]]) as usize;
        let mut off = 84usize;
        for _ in 0..n {
            off += 12; // normal
            for _ in 0..3 {
                let x = f32::from_le_bytes([data[off], data[off + 1], data[off + 2], data[off + 3]]);
                off += 4;
                let y = f32::from_le_bytes([data[off], data[off + 1], data[off + 2], data[off + 3]]);
                off += 4;
                let z = f32::from_le_bytes([data[off], data[off + 1], data[off + 2], data[off + 3]]);
                off += 4;
                vertices.push(Vertex { position: [x, y, z] });
            }
            off += 2; // attribute
        }
        for t in 0..n {
            triangles.push(Triangle {
                vertices: [t * 3, t * 3 + 1, t * 3 + 2],
                material: 0,
            });
        }
    } else {
        let text = String::from_utf_lossy(&data);
        let mut tri: Vec<[f32; 3]> = Vec::new();
        for line in text.lines() {
            let line = line.trim();
            if line.starts_with("vertex") {
                let rest = line[6..].trim();
                if let Some(v) = parse_vec3(rest) {
                    tri.push(v);
                }
            } else if line.starts_with("endfacet") {
                if tri.len() >= 3 {
                    let base = vertices.len();
                    for v in tri.drain(..) {
                        vertices.push(Vertex { position: v });
                    }
                    triangles.push(Triangle {
                        vertices: [base, base + 1, base + 2],
                        material: 0,
                    });
                }
                tri.clear();
            }
        }
    }
    let materials = vec![Material {
        name: String::new(),
        diffuse: [1.0, 1.0, 0.0],
    }];
    Ok(Model {
        vertices,
        triangles,
        materials,
    })
}

pub fn load(path: &str) -> Result<Model, Error> {
    let lower = path.to_lowercase();
    if lower.ends_with(".stl") {
        load_stl(path)
    } else {
        load_obj(path)
    }
}
