// Projection and rasterisation of a triangle soup into a character buffer.
use crate::inputs::Model;

#[derive(Clone, Copy)]
pub struct Cell {
    pub ch: char,
    pub color: [u8; 3],
}

impl Cell {
    pub fn blank() -> Cell {
        Cell {
            ch: ' ',
            color: [0, 0, 0],
        }
    }
}

pub const GRADIENT: [char; 10] = [' ', '.', ':', '-', '=', '+', '*', '%', '#', '@'];
pub const BG: [u8; 3] = [25, 25, 25];

pub struct Frame {
    pub cells: Vec<Cell>,
    pub width: usize,
    pub height: usize,
}

/// Build the character/colour buffer for the given model list.
pub fn render(models: &[Model], w: usize, h: usize, rot: (f32, f32, f32), blue: bool) -> Frame {
    let total = h * (w + 1);
    let mut cells: Vec<Cell> = vec![Cell::blank(); total];

    // ---- gather geometry -------------------------------------------------
    let mut positions: Vec<[f32; 3]> = Vec::new();
    let mut tris: Vec<([usize; 3], usize, [f32; 3])> = Vec::new();
    for m in models {
        let base = positions.len();
        for v in &m.vertices {
            positions.push(rotate(v.position, rot));
        }
        for t in &m.triangles {
            let a = positions[base + t.vertices[0]];
            let b = positions[base + t.vertices[1]];
            let c = positions[base + t.vertices[2]];
            let n = normal(a, b, c);
            tris.push((
                [base + t.vertices[0], base + t.vertices[1], base + t.vertices[2]],
                t.material,
                n,
            ));
        }
    }
    if positions.is_empty() || tris.is_empty() {
        return Frame { cells, width: w, height: h };
    }

    // ---- normalisation scale --------------------------------------------
    let mut mmax = 0.0f32;
    for p in &positions {
        for k in 0..3 {
            if p[k] > mmax {
                mmax = p[k];
            }
        }
    }
    if mmax <= 0.0 {
        mmax = 1.0;
    }
    let inv = 1.0 / mmax;

    // ---- fit -------------------------------------------------------------
    let hh = if h >= 2 { h - 2 } else { 1 } as f32;
    let scale = ((w as f32) / 2.0).min(hh);

    let cx = w as f32 / 2.0;
    let cy = h as f32 / 2.0;

    // screen positions
    let mut sx: Vec<f32> = Vec::with_capacity(positions.len());
    let mut sy: Vec<f32> = Vec::with_capacity(positions.len());
    let mut sz: Vec<f32> = Vec::with_capacity(positions.len());
    for p in &positions {
        let x = p[0] * inv;
        let y = p[1] * inv;
        let z = p[2] * inv;
        sx.push(x * scale + cx);
        sy.push(cy - y * scale / 2.0);
        sz.push(z);
    }

    // ---- rasterise -------------------------------------------------------
    for (idx, mat, n) in &tris {
        let shade = n[2];
        if shade <= 0.0 {
            continue;
        }
        let g = GRADIENT[((shade * 10.0).floor() as i32).clamp(1, 9) as usize];
        let color = if blue {
            [0u8, 0, 0]
        } else {
            let d = models[0].materials.get(*mat).map(|m| m.diffuse);
            match d {
                Some(d) => [(d[0] * 255.0) as u8, (d[1] * 255.0) as u8, (d[2] * 255.0) as u8],
                None => [1, 1, 1],
            }
        };
        let (a, b, c) = (idx[0], idx[1], idx[2]);
        fill_tri(&mut cells, w, h, sx[a], sy[a], sx[b], sy[b], sx[c], sy[c], g, color);
    }

    Frame { cells, width: w, height: h }
}

fn rotate(p: [f32; 3], rot: (f32, f32, f32)) -> [f32; 3] {
    let (rx, ry, rz) = rot;
    let mut v = p;
    if rx != 0.0 {
        let (s, c) = rx.sin_cos();
        v = [v[0], v[1] * c - v[2] * s, v[1] * s + v[2] * c];
    }
    if ry != 0.0 {
        let (s, c) = ry.sin_cos();
        v = [v[0] * c + v[2] * s, v[1], -v[0] * s + v[2] * c];
    }
    if rz != 0.0 {
        let (s, c) = rz.sin_cos();
        v = [v[0] * c - v[1] * s, v[0] * s + v[1] * c, v[2]];
    }
    v
}

fn normal(a: [f32; 3], b: [f32; 3], c: [f32; 3]) -> [f32; 3] {
    let u = [b[0] - a[0], b[1] - a[1], b[2] - a[2]];
    let v = [c[0] - a[0], c[1] - a[1], c[2] - a[2]];
    let n = [
        u[1] * v[2] - u[2] * v[1],
        u[2] * v[0] - u[0] * v[2],
        u[0] * v[1] - u[1] * v[0],
    ];
    let len = (n[0] * n[0] + n[1] * n[1] + n[2] * n[2]).sqrt();
    if len == 0.0 {
        [0.0, 0.0, 0.0]
    } else {
        [n[0] / len, n[1] / len, n[2] / len]
    }
}

fn fill_tri(
    cells: &mut Vec<Cell>,
    w: usize,
    h: usize,
    x0: f32,
    y0: f32,
    x1: f32,
    y1: f32,
    x2: f32,
    y2: f32,
    ch: char,
    color: [u8; 3],
) {
    let minx = x0.min(x1).min(x2).floor() as i32;
    let maxx = x0.max(x1).max(x2).ceil() as i32;
    let miny = y0.min(y1).min(y2).floor() as i32;
    let maxy = y0.max(y1).max(y2).ceil() as i32;
    for py in miny..=maxy {
        if py < 0 || py >= h as i32 {
            continue;
        }
        for px in minx..=maxx {
            if px < 0 || px >= w as i32 {
                continue;
            }
            let cx = px as f32;
            let cy = py as f32;
            if inside(cx, cy, x0, y0, x1, y1, x2, y2) {
                let i = py as usize * (w + 1) + px as usize;
                cells[i] = Cell { ch, color };
            }
        }
    }
}

fn inside(px: f32, py: f32, x0: f32, y0: f32, x1: f32, y1: f32, x2: f32, y2: f32) -> bool {
    let d1 = (px - x1) * (y0 - y1) - (x0 - x1) * (py - y1);
    let d2 = (px - x2) * (y1 - y2) - (x1 - x2) * (py - y2);
    let d3 = (px - x0) * (y2 - y0) - (x2 - x0) * (py - y0);
    let has_neg = d1 < 0.0 || d2 < 0.0 || d3 < 0.0;
    let has_pos = d1 > 0.0 || d2 > 0.0 || d3 > 0.0;
    !(has_neg && has_pos)
}
