fn rotate(p: [f32; 3], rot: (f32, f32, f32)) -> [f32; 3] {
    let (rx, ry, rz) = rot;
    let mut v = p;
    if rx != 0.0 {
        let (s, c) = rx.sin_cos();
        v = [v[0], v[1] * c - v[2] * s, v[1] * s + v[2] * c];
    }
    if ry != 0.0 {
        let (s, c) = ry.sin_cos();
        v = [v[0] * c + v[2] * s, v[1], -v[0] * s + v[2] * c];
    }
    if rz != 0.0 {
        let (s, c) = rz.sin_cos();
        v = [v[0] * c - v[1] * s, v[0] * s + v[1] * c, v[2]];
    }
    v
