mod args;
mod inputs;
mod rasterizer;

use rasterizer::{Cell, Frame};
use std::io::Write;

fn main() {
    let a = args::parse();
    if a.sub.is_none() {
        interactive(&a);
        return;
    }
    let models = load_all(&a.inputs);
    match a.webify {
        Some(n) => webify(&models, &a, n),
        None => image(&models, &a),
    }
}

fn load_all(inputs: &[String]) -> Vec<inputs::Model> {
    let mut names: Vec<String> = Vec::new();
    for arg in inputs {
        for part in arg.split(' ') {
            if part.is_empty() {
                continue;
            }
            names.push(part.to_string());
        }
    }
    let mut out: Vec<inputs::Model> = Vec::new();
    for n in &names {
        match inputs::load(n) {
            Ok(m) => out.push(m),
            Err(e) => {
                eprintln!();
                eprintln!(
                    "thread 'main' panicked at src/inputs.rs:126:39:\ncalled `Result::unwrap()` on an `Err` value: \"filename: [{}] couldn't load, tobj couldnt load/parse OBJ. {}\"\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace",
                    n, e
                );
                std::process::exit(101);
            }
        }
    }
    out
}

fn image(models: &[inputs::Model], a: &args::Args) {
    let w = a.width.unwrap();
    let h = a.height.unwrap();
    let frame = rasterizer::render(models, w, h, rot_of(a), a.blue);
    let out = render_buffer(&frame, a.blue);
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(out.as_bytes());
}

fn rot_of(a: &args::Args) -> (f32, f32, f32) {
    (a.rotate.x.unwrap_or(0.0), a.rotate.y.unwrap_or(0.0), a.rotate.z.unwrap_or(0.0))
}

/// Build the exact output string for one frame.
pub fn render_buffer(frame: &Frame, blue: bool) -> String {
    let w = frame.width;
    let h = frame.height;
    let total = h * (w + 1);
    // Determine occupied rows in the raster (grid of w-1 columns, h rows).
    let cols = if w >= 1 { w - 1 } else { 0 };
    let mut first: Option<usize> = None;
    let mut last: Option<usize> = None;
    for y in 0..h {
        let mut any = false;
        for x in 0..cols {
            if frame.cells[y * (w + 1) + x].ch != ' ' {
                any = true;
                break;
            }
        }
        if any {
            if first.is_none() {
                first = Some(y);
            }
            last = Some(y);
        }
    }
    let rows = match (first, last) {
        (Some(f), Some(l)) => l - f + 1,
        _ => 0,
    };
    let mut buf: Vec<Cell> = Vec::with_capacity(total);
    if rows > 0 {
        let k = ((h - rows) / 2) + if (h - rows) % 2 == 1 { 1 } else { 0 };
        let prefix = k * w + 1;
        for _ in 0..prefix.min(total) {
            buf.push(Cell::blank());
        }
        let f = first.unwrap();
        for r in 0..rows {
            buf.push(Cell { ch: '\n', color: [0, 0, 0] });
            for x in 0..cols {
                if buf.len() >= total {
                    break;
                }
                buf.push(frame.cells[(f + r) * (w + 1) + x]);
            }
        }
    }
    while buf.len() < total {
        buf.push(Cell::blank());
    }
    buf.truncate(total);
    let mut s = String::with_capacity(total * 40);
    for c in &buf {
        if blue && false {
            s.push(c.ch);
        } else {
            let (r, g, b) = (c.color[0], c.color[1], c.color[2]);
            s.push_str(&format!("\x1b[48;2;25;25;25m\x1b[38;2;{};{};{}m{}\x1b[49m\x1b[39m", r, g, b, c.ch));
        }
    }
    s
}

fn webify(models: &[inputs::Model], a: &args::Args, frames: usize) {
    let w = a.width.unwrap();
    let h = a.height.unwrap();
    let mut s = String::from("let frames = [\n");
    let (rx, ry, rz) = rot_of(a);
    for i in 0..frames {
        let t = i as f32 * 0.1;
        let frame = rasterizer::render(models, w, h, (rx + t, ry + t, rz), a.blue);
        if i > 0 {
            s.push_str(",\n");
        }
        s.push('`');
        s.push('\n');
        s.push_str(&render_buffer(&frame, a.blue));
        s.push('`');
    }
    s.push_str("];\n");
    print!("{}", s);
}

fn interactive(a: &args::Args) {
    let (tw, th) = match args::crate_size() {
        Some(s) => s,
        None => {
            eprintln!("Error: IoError(Os {{ code: 25, kind: Uncategorized, message: \"Inappropriate ioctl for device\" }})");
            std::process::exit(1);
        }
    };
    let models = load_all(&a.inputs);
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    if !a.blue {
        let _ = lock.write_all(b"\x1b[?25l");
    }
    let (rx, ry, rz) = rot_of(a);
    let mut t: f32 = 0.0;
    loop {
        let frame = rasterizer::render(&models, tw, th, (rx + t, ry + t, rz), a.blue);
        let _ = lock.write_all(b"\x1b[1;1H");
        if a.blue {
            let cols = if tw >= 1 { tw - 1 } else { 0 };
            let _ = lock.write_all(b"\n");
            for y in 0..th {
                let mut line = String::new();
                for x in 0..cols {
                    line.push(frame.cells[y * (tw + 1) + x].ch);
                }
                let _ = lock.write_all(line.as_bytes());
                let _ = lock.write_all(b"\n");
            }
        } else {
            let s = render_buffer(&frame, false);
            let _ = lock.write_all(s.as_bytes());
        }
        let _ = lock.flush();
        t += 0.02;
    }
}
