import math,itertools
data=[(20,3,6,1),(20,10,20,8),(30,10,20,8),(40,10,22,8),(40,20,40,18),(30,20,30,15),(60,20,42,18),(80,30,62,28),(20,8,18,6),(40,16,34,14)]
def cells(lo,hi):
