s=s.replace('''fn webify(models: &[inputs::Model], a: &args::Args, frames: usize) {''','''/// HTML span variant used by the `-j/--webify` export.
pub fn render_span_buffer(frame: &Frame) -> String {
    let w = frame.width;
    let h = frame.height;
    let total = h * (w + 1);
    let cols = if w >= 1 { w - 1 } else { 0 };
    let mut first: Option<usize> = None;
    let mut last: Option<usize> = None;
    for y in 0..h {
        let mut any = false;
        for x in 0..cols {
            if frame.cells[y * (w + 1) + x].ch != ' ' {
                any = true;
                break;
            }
        }
        if any {
            if first.is_none() {
                first = Some(y);
            }
            last = Some(y);
        }
    }
    let rows = match (first, last) {
        (Some(f), Some(l)) => l - f + 1,
        _ => 0,
    };
    let mut buf: Vec<Cell> = Vec::with_capacity(total);
    if rows > 0 {
        let k = ((h - rows) / 2) + if (h - rows) % 2 == 1 { 1 } else { 0 };
        let prefix = k * w + 1;
        for _ in 0..prefix.min(total) {
            buf.push(Cell::blank());
        }
        let f = first.unwrap();
        for r in 0..rows {
            buf.push(Cell { ch: '\\n', color: [0, 0, 0] });
            for x in 0..cols {
                if buf.len() >= total {
                    break;
                }
                buf.push(frame.cells[(f + r) * (w + 1) + x]);
            }
        }
    }
    while buf.len() < total {
        buf.push(Cell::blank());
    }
    buf.truncate(total);
    let mut s = String::with_capacity(total * 34);
    for c in &buf {
        let (r, g, b) = (c.color[0], c.color[1], c.color[2]);
        s.push_str(&format!("<span style=\\"color:rgb({},{},{})\\">{}", r, g, b, c.ch));
    }
    s
}

fn webify(models: &[inputs::Model], a: &args::Args, frames: usize) {''')
